// Page renderers share the same in-memory model as the home and inventory.
const plotLabel=state=>({empty:T('等待种植','Ready to plant'),growing:T('慢慢长大','Growing'),ready:T('可以收获','Ready to harvest'),withered:T('需要清理','Withered'),locked:T('尚未解锁','Locked')})[state];
const treeArt=id=>'tree'+(TREE_IDS.indexOf(id)+1);
const treeName=id=>nameOf(id+'_sapling').replace(/种苗|树苗| sapling| seedling/gi,'');
const toolCost=id=>({watering:[0,900,2200],shovel:[0,800,2000],fertilizer:[0,1200,3000]})[id][S.gardenTools[id]]||0;
const plotCost=i=>[100,1000,5000,10000,30000][i];
const clearCost=()=>S.gardenTools.shovel>=3?40:S.gardenTools.shovel>=2?60:80;
const maxHarvests=tree=>({fruit_tree:8,care_tree:7,gift_tree:6,money_tree:8,golden_apple_tree:9})[tree]+(UI.season==='winter'?1:0);
const growthFactor=()=> (UI.weather==='sunny'?.95:UI.weather==='breezy'?.97:1)*(UI.season==='spring'?.9:1);
const growthSeconds=(tree,repeat=false)=>Math.round(({fruit_tree:8,care_tree:10,gift_tree:12,money_tree:repeat?36:72,golden_apple_tree:repeat?48:96})[tree]*3600*growthFactor()*(S.cards.active==='best'?.88:1));
const waterPercent=()=>[0,5,8,10][S.gardenTools.watering]+(UI.weather==='rainy'?5:0)+(UI.season==='summer'?3:0);
function gardenCareMinutes(kind){const p=S.garden[UI.plot],duration=p.duration||growthSeconds(p.tree||'fruit_tree',p.harvests>0),ratio=kind==='water'?waterPercent()/100:kind==='normal_fertilizer'?.2:.35,maximum=kind==='water'?21600:kind==='normal_fertilizer'?36000:64800;return Math.max(0,Math.floor(Math.min(duration*ratio,maximum,duration*.6-(p.careReduction||0),Math.max(0,(p.seconds||duration)-10))/60));}
const waterReduction=()=>gardenCareMinutes('water');
function gardenEnvironmentExplanation(){return T('新种小树生长用时 ×'+growthFactor().toFixed(2)+'；浇水减少 '+waterPercent()+'%；额外掉落 +'+((UI.weather==='cloudy'?5:0)+(UI.season==='autumn'?10:0))+'%；'+(UI.season==='winter'?'冬季种植多 1 次收获。':'当前季节不增加收获次数。'),'New growth time ×'+growthFactor().toFixed(2)+'; watering saves '+waterPercent()+'%; extra drops +'+((UI.weather==='cloudy'?5:0)+(UI.season==='autumn'?10:0))+'%; '+(UI.season==='winter'?'winter planting adds one harvest.':'no extra harvests this season.'));}
const workEnergy=()=>UI.weather==='breezy'?10:12;
const workReward=()=>24+S.level-1+(UI.weather==='rainy'?-4:0)+(UI.season==='autumn'?2:0)+(S.cards.active==='friend'?Math.min(8,80-S.cards.workUsed):0)+(S.bonuses?.workCoinBonus||0);
function gardenPage(){const g=S.garden[UI.plot];return pageTitle(T('慢慢长大的花园','A slowly growing garden'),'A LITTLE GARDEN',environmentButton())+'<div class="split-layout"><section class="garden-board card '+environmentClass()+'"><div class="card-head"><div><h2>'+T('五块土地，一点期待','Five plots, little hopes')+'</h2><p class="hint">'+T('已收获 '+S.harvestTotal+' 次 · 选择一块土地照料','Harvested '+S.harvestTotal+' times · Select a plot to care for')+'</p></div>'+b(T('工具','Tools'),'tools','','','sliders')+'</div><div class="plot-grid '+environmentClass()+'">'+S.garden.map((p,i)=>'<button class="plot '+p.state+' '+environmentClass()+'" aria-pressed="'+(UI.plot===i)+'" data-act="select-plot" data-arg="'+i+'"><span class="plot-label">0'+(i+1)+'<span>'+plotLabel(p.state)+'</span></span>'+decor()+(p.tree?img(treeArt(p.tree)):'<span class="plot-empty">'+I(p.state==='locked'?'lock':'plus')+'</span>')+'<strong>'+(p.tree?E(treeName(p.tree)):p.state==='locked'?T('再拓一片小天地','Room for more'):T('种下一份期待','Plant a little hope'))+'</strong><small>'+ (p.state==='growing'?timeText(p.seconds):p.state==='locked'?money(plotCost(i)):p.state==='ready'?T('果实已经成熟啦','The fruit is ready'):p.state==='withered'?T('清理后可以重新种植','Clear to plant again'):T('从背包选择种苗','Choose a seedling from your bag'))+'</small>'+(p.state==='growing'?bar(growthSeconds(p.tree)-p.seconds,growthSeconds(p.tree)):'')+'</button>').join('')+'</div><div class="garden-meta"><span>'+I(environmentIcon())+gardenEnvironmentExplanation()+'</span></div>'+(!S.claimed.includes('garden-compensation')?'<div class="notice-box row between"><span>'+T('花园修复补偿 · 300 金币 + 普通肥料 ×1','Garden compensation · 300 coins + fertilizer ×1')+'</span>'+b(T('领取','Claim'),'garden-compensation','','small','gift')+'</div>':'')+'</section><aside class="garden-aside card"><div class="section-heading"><h2>'+T('第 '+(UI.plot+1)+' 块土地','Plot '+(UI.plot+1))+'</h2>'+pill(plotLabel(g.state))+'</div>'+gardenDetail(g)+'</aside></div>';}
function gardenDetail(g){
 const owned=g.tree,ready=g.state==='ready',dead=g.state==='withered',growing=g.state==='growing';
 if(g.state==='locked')return '<div class="empty">'+I('lock')+'<h3>'+T('多一点生长的空间','More room to grow')+'</h3><p class="hint">'+T('解锁后可以种植任意树种。','Unlock to plant any tree.')+'</p></div>'+b(T('解锁土地 · ','Unlock plot · ')+money(plotCost(UI.plot)),'unlock-plot','','primary block','',S.coins<plotCost(UI.plot));
 if(g.state==='empty')return '<div class="empty">'+I('sprout')+'<h3>'+T('这里会长出什么呢','What will grow here?')+'</h3><p class="hint">'+T('水果、礼物、护理、金币与金苹果树。','Fruit, gift, care, money and golden apple trees.')+'</p></div>'+b(T('选择种苗','Choose a seedling'),'plant-dialog','','primary block','plus')+'<p class="hint" style="margin-top:15px">'+gardenEnvironmentExplanation()+'</p>';
 return '<div class="detail-hero"><div class="detail-art">'+img(treeArt(owned))+'</div><div><h3>'+E(treeName(owned))+'</h3><p class="hint">'+T('已收获 ','Harvests ')+g.harvests+' / '+(g.maxHarvests||maxHarvests(owned))+'</p></div></div><p class="hint" style="margin:16px 0">'+(ready?T('成熟的果实，等你来摘。','Ripe fruit, waiting for you.'):dead?T('小树完成了它的旅程，清理后可重新种植。','This tree has finished its journey. Clear it to plant again.'):T('预计 '+timeText(g.seconds)+' 后成熟。','Ready in '+timeText(g.seconds)+'.'))+'</p><div class="garden-actions">'+(ready?b(T('收获果实','Harvest'),'harvest','','primary wide','gift'):dead?b(T('清理枯树 · ','Clear tree · ')+money(clearCost()),'clear-plot','','primary wide','trash',S.coins<clearCost()):b(T('浇水 · −'+waterReduction()+' 分钟','Water · −'+waterReduction()+' min'),'water','','primary wide','drop',g.waterDay===S.day||waterReduction()===0)+b(T('普通肥料','Fertilizer')+' ×'+(S.inventory.normal_fertilizer||0),'fertilize','normal_fertilizer','','sprout',!S.inventory.normal_fertilizer||g.fertilizerDay===S.day)+b(T('爱心肥料','Heart fertilizer')+' ×'+(S.inventory.heart_fertilizer||0),'fertilize','heart_fertilizer','','heart',!S.inventory.heart_fertilizer||g.fertilizerDay===S.day))+(growing?b(g.nutrient?T('营养液已生效','Nutrient active'):T('营养液 · 本轮额外收获','Nutrient · Extra harvest'),'nutrient','','wide','drop',!S.inventory.harvest_nutrient||g.nutrientDay===S.day):'')+b(T('园艺用品','Garden supplies'),'garden-shop','','wide','shop')+(!dead?b(T('移除小树','Remove tree'),'clear-plot','','wide danger','trash'):'')+'</div><div class="divider"></div><h3>'+T('照料预估','Care preview')+'</h3><p class="hint" style="margin-top:10px">'+(growing?T('普通肥料减少 '+gardenCareMinutes('normal_fertilizer')+' 分钟，并提高额外掉落概率；爱心肥料减少 '+gardenCareMinutes('heart_fertilizer')+' 分钟，并提高稀有物品权重。营养液保证本轮额外掉落一次。','Fertilizer saves '+gardenCareMinutes('normal_fertilizer')+' minutes and boosts extra drops; heart fertilizer saves '+gardenCareMinutes('heart_fertilizer')+' minutes and boosts rare drops. Nutrient guarantees an extra drop this cycle.'):gardenEnvironmentExplanation())+'</p><p class="hint">'+T('每块土地每天可浇水、施肥和使用营养液各一次。照料最多减少本轮 60% 时间。','Each plot accepts water, fertilizer and nutrient once daily. Care can remove at most 60% of a growth cycle.')+'</p>'+(g.waterDay===S.day?'<p class="hint">'+T('今天已经浇过水了。','Already watered today.')+'</p>':'');
}
function skillEffect(k){const n=S.skills[k].level;return ({study:T('专注金币 +'+n*2+'%','Focus coins +'+n*2+'%'),cooking:T('食物恢复 +'+n*2+'%','Food recovery +'+n*2+'%'),garden:T('照料效率 +'+n*2+'%','Garden care +'+n*2+'%'),exercise:T('体力恢复 +'+n*2+'%','Energy recovery +'+n*2+'%')})[k];}
const scheduleOffer=i=>({minutes:[45,120,240][i],energy:[12,30,55][i],xp:[10,23,50][i],coins:Math.round((24+S.level-1)*[1.6,4.2,8.5][i]*1.15*(S.cards.active==='best'?1.1:1))});
function schedulePage(){return schedulePageFull();}
function scheduleRunning(){const a=S.schedule;return '<section class="running-card card" style="margin-top:20px"><div>'+petImage('work')+'</div><div class="grow"><p class="eyebrow">IN GOOD COMPANY</p><h2>'+skillName(a.category)+' · '+(a.neighbor?T('和 '+roleName(a.neighbor)+' 一起','with '+roleName(a.neighbor)):T('安静地忙碌中','A little time of their own'))+'</h2><p class="hint">'+T('正在安静地做自己的事情。回来后领取奖励。','Enjoying a little activity. Rewards will be ready afterward.')+'</p><h3 class="countdown" style="margin:18px 0">'+timeText(a.remaining)+'</h3>'+bar(a.total-a.remaining,a.total)+'<div class="row wrap" style="margin-top:20px">'+b(T('取消日程','Cancel activity'),'cancel-schedule','','','close')+b(T('预览：完成时间','Preview: finish time'),'advance','schedule','','sliders')+'</div></div></section>';}
function scheduleSettlement(){const a=S.schedulePending;return '<section class="card" style="margin-top:20px"><p class="eyebrow">A LITTLE PROGRESS</p><h2>'+T('今天也做得很好','A little more progress today')+'</h2><p class="hint" style="margin:12px 0">'+skillName(a.category)+' · '+a.minutes+' '+T('分钟 · 完成了一段小日程','min · A little activity complete')+'</p><div class="row wrap">'+money(a.coins)+pill(T('技能经验 +','Skill XP +')+a.xp,'award')+'</div><div class="divider"></div><h3>'+T('再选一份小奖励','Choose a little extra')+'</h3><div class="reward-choice" style="margin-top:15px">'+b(T('零花钱 +36','Pocket money +36'),'claim-schedule','coins','reward-option','coin')+(a.size===0?'':b(T('技能相关物品 ×2','Skill supply ×2'),'claim-schedule','item','reward-option','gift'))+'</div></section>';}
function focusPage(){const f=S.focus;return pageTitle(T('和你一起，专心一会儿','A little focus, together'),'ONE THING AT A TIME',pill(T('今日完成 '+f.today+' 次',f.today+' sessions today'),'coffee'))+'<div class="focus-layout"><section class="card focus-stage"><div class="tabs" style="justify-content:center">'+['focus','rest'].map(p=>'<button class="tab" aria-selected="'+(f.phase===p)+'" data-act="focus-phase" data-arg="'+p+'">'+(p==='focus'?T('专注','Focus'):T('休息','Break'))+'</button>').join('')+'</div><div class="focus-orb"><span class="eyebrow">'+(f.running?T('静静陪着你','RIGHT HERE WITH YOU'):T('准备好了就开始','TAKE YOUR TIME'))+'</span><strong class="time" id="focus-time">'+timeText(f.remaining)+'</strong><span>'+T('第 '+f.round+' / '+f.rounds+' 轮','Round '+f.round+' / '+f.rounds)+'</span></div><div class="row wrap" style="justify-content:center">'+b(f.running?T('暂停','Pause'):T('开始','Start'),'focus-toggle','','primary',f.running?'pause':'play')+b(T('重置','Reset'),'focus-reset','','','refresh')+'</div><div class="focus-pet">'+petImage('idle')+'</div></section><aside class="card"><h2>'+T('找到自己的节奏','Find your own rhythm')+'</h2><p class="hint" style="margin:12px 0 25px">'+T('计时会在页面切换后继续，首页会显示运行状态。','The timer continues between pages and appears on your home screen.')+'</p><div class="form-grid">'+numberField('focus-minutes',T('专注时长（分钟）','Focus minutes'),f.focus,'focus-length',1,180)+numberField('rest-minutes',T('休息时长（分钟）','Break minutes'),f.rest,'rest-length',1,60)+numberField('focus-rounds',T('轮数','Rounds'),f.rounds,'focus-rounds',1,8)+'</div><div class="divider"></div><h3>'+T('每次专注的小奖励','A reward for each session')+'</h3><p class="hint" style="margin-top:10px">'+T('完成一轮获得 24 金币，学习技能提供加成。','Each focus round earns 24 coins with a study skill bonus.')+'</p>'+b(T('预览：完成本轮','Preview: finish round'),'advance','focus','block','sliders')+'</aside></div>';}
function numberField(id,label,value,change,min,max){return '<label class="field" for="'+id+'"><span>'+label+'</span><input class="text-field" id="'+id+'" type="number" data-change="'+change+'" min="'+min+'" max="'+max+'" value="'+value+'"></label>';}
function cardsPage(){return pageTitle(T('多一点陪伴，多一点心意','A little more together'),'COMPANION PASSES')+'<div class="pass-grid">'+['friend','best'].map(k=>{const best=k==='best',days=S.cards[k+'Days'],active=S.cards.active===k;return '<section data-tone="'+(best?'rose':'mint')+'" class="pass-card card '+(active?'active':'')+'"><div class="row between">'+pill(best?'BEST FRIEND':'LITTLE FRIEND','heart')+(active?pill(T('正在生效','Active'),'check'):'')+'</div><h2 style="margin-top:22px">'+(best?T('挚友搭子卡','Best friend pass'):T('好友搭子卡','Friend pass'))+'</h2><p class="hint">'+(days?T('剩余 '+days+' 天','Valid for '+days+' more days'):T('陪伴 30 天','30 days of companionship'))+'</p><ul class="benefits"><li>'+T('每日领取 ','Daily gift: ')+(best?'50':'15')+' '+T('金币','coins')+'</li><li>'+(best?T('每日额外 30 小心心','30 extra hearts daily'):T('打工额外 +8 金币，每日上限 80','Work earns +8 coins, up to 80 a day'))+'</li>'+(best?'<li>'+T('日程金币 +10%','Activity coins +10%')+'</li><li>'+T('花园生长时间 −12%，额外收获概率 +20%','Garden grows 12% faster; +20% extra harvest chance')+'</li>':'<li>'+T('零花钱慢慢攒起来','A little extra pocket money')+'</li>')+'</ul><div class="row between"><strong>'+money(best?90:10,'hearts')+' / 30 '+T('天','days')+'</strong>'+b(days?T('续期','Renew'):T('购买','Get pass'),'buy-pass',k,'primary','ticket',(!best&&S.cards.active==='best')||days>=90)+'</div></section>';}).join('')+'</div><section class="card" style="margin-top:20px"><div class="card-head"><div><h2>'+T('今天的搭子心意','Your daily companion gift')+'</h2><p class="hint">'+(S.cards.active?T('当前权益：','Active benefits: ')+(S.cards.active==='best'?T('挚友搭子卡','Best friend pass'):T('好友搭子卡','Friend pass')):T('购买搭子卡后可领取','Available with a companion pass'))+'</p></div>'+b(S.cards.claimed?T('今日已领取','Claimed today'):T('领取每日奖励','Claim daily gift'),'claim-pass','','primary','gift',S.cards.claimed||!S.cards.active)+'</div><div class="metric-grid"><div class="metric"><small>'+T('打工加成已用','Work bonus used')+'</small><strong>'+S.cards.workUsed+' / 80</strong></div><div class="metric"><small>'+T('花园加成次数','Garden bonuses')+'</small><strong>'+S.cards.gardenUsed+'</strong></div><div class="metric"><small>'+T('续期上限','Maximum validity')+'</small><strong>90 '+T('天','days')+'</strong></div></div></section>';}
const rarityLabel=r=>({common:T('普通','Common'),uncommon:T('优秀','Uncommon'),rare:T('稀有','Rare'),epic:T('史诗','Epic'),legendary:T('传说','Legendary'),jackpot:T('大奖','Jackpot')})[r]||r;
const rewardText=r=>r.kind==='coins'?F(r.amount)+' '+T('金币','coins'):r.kind==='hearts'?F(r.amount)+' '+T('小心心','hearts'):E(nameOf(r.item))+' ×'+r.amount;
function resultsGrid(results){return '<div class="result-grid">'+results.map(r=>'<div class="result-item rarity-'+r.rarity+'">'+(r.kind==='item'?img(r.item):r.kind==='coins'?img('coin'):I('heart'))+'<strong>'+rewardText(r)+'</strong><small>'+rarityLabel(r.rarity)+'</small></div>').join('')+'</div>';}
function gachaPage(){const heart=UI.machine==='heart',g=S.gacha;return pageTitle(T('装满小惊喜的扭蛋机','A machine full of little surprises'),'A LITTLE LUCK',b(T('抽取记录','Draw history'),'gacha-history','','','book'))+'<div class="tabs" style="margin-bottom:20px">'+['apple','heart'].map(k=>'<button class="tab" aria-selected="'+(UI.machine===k)+'" data-act="machine" data-arg="'+k+'">'+(k==='apple'?T('金苹果扭蛋','Golden apple gacha'):T('小心心扭蛋','Heart gacha'))+'</button>').join('')+'</div><div class="gacha-layout"><section class="card gacha-stage"><div class="gacha-machine '+(g.drawing?'drawing':'')+'"><div class="gacha-globe">'+['golden_apple','strawberry_cake','ad_milk','shiny_sticker','apple'].map(id=>img(id)).join('')+'</div><div class="gacha-base"><strong>POCKET</strong><div class="gacha-knob">'+I('flower')+'</div><span>A LITTLE SURPRISE</span></div></div><h2>'+(heart?T('把金苹果变成心意','Turn golden apples into hearts'):T('下一颗，会是什么呢','What will the next one be?'))+'</h2><p class="hint">'+(heart?T('每抽 1 金苹果 · 十连至少 100 小心心','1 golden apple per draw · At least 100 hearts per ten'):T('金币或扭蛋券都可以','Use coins or gacha tickets'))+'</p></section><aside class="card"><h2>'+T('转动一点幸运','A little turn of luck')+'</h2><div class="row wrap" style="margin:18px 0">'+(heart?pill(T('金苹果 ','Golden apples ')+(S.inventory.golden_apple||0),'gift'):money(S.coins)+pill(T('扭蛋券 ','Tickets ')+S.tickets,'ticket'))+'</div>'+(!heart?'<div class="choice-grid" style="margin-bottom:18px">'+['coins','tickets'].map(p=>'<button class="choice-button '+(UI.payment===p?'active':'')+'" data-act="payment" data-arg="'+p+'">'+(p==='coins'?T('金币支付','Pay with coins'):T('扭蛋券支付','Pay with tickets'))+'</button>').join('')+'</div>':'')+'<div class="gap">'+b(T('抽 1 次 · ','Draw one · ')+(heart?'1 '+T('金苹果','apple'):UI.payment==='tickets'?'1 '+T('券','ticket'):money(500)),'draw-confirm','1','primary block','gift',g.drawing)+b(T('抽 10 次 · ','Draw ten · ')+(heart?'10 '+T('金苹果','apples'):UI.payment==='tickets'?'10 '+T('券','tickets'):money(5000)),'draw-confirm','10','block','gift',g.drawing)+(g.drawing?b(T('跳过动画','Skip animation'),'skip-draw','','block','chevron'):'')+'</div><div class="divider"></div><p class="hint">'+(heart?T('十连保底会在结算时补足奖励。','The ten-draw minimum is applied at settlement.'):T('大奖保底进度 '+g.pity+' / 1000','Jackpot guarantee '+g.pity+' / 1000'))+'</p>'+b(T('查看完整概率','View all probabilities'),'probabilities','','block','info')+b(g.starter?T('新手礼包已领取','Starter gift claimed'):T('领取新手礼包 · 扭蛋券 ×10','Starter gift · 10 tickets'),'gacha-starter','','block','gift',g.starter)+'</aside></div>'+ (g.results.length?'<section class="card" style="margin-top:20px"><div class="card-head"><div><h2>'+T('这次的小惊喜','Your latest surprises')+'</h2><p class="hint">'+T('奖励已放入资源和背包。','Rewards have been added to your wallet and bag.')+'</p></div>'+b(T('预览结果图片','Preview results image'),'image-preview','gacha','','image')+'</div>'+resultsGrid(g.results)+'</section>':'')+ticketSourcesCard();}
function achievementGroup(a){return a.category==='hidden'?'hidden':['care','daily','date'].includes(a.category)?'companion':['growth'].includes(a.category)?'growth':['schedule','pomodoro'].includes(a.category)?'schedule':'life';}
function achievementsPage(){const tabs={all:T('全部','All'),companion:T('陪伴','Companionship'),growth:T('成长','Growth'),life:T('生活','Life'),schedule:T('专注与日程','Focus & activities'),hidden:T('隐藏','Hidden')},ready=DATA.achievements.filter(a=>achievementComplete(a)&&!S.achievementClaimed.includes(a.id));const list=DATA.achievements.filter(a=>(UI.achievementTab==='all'||achievementGroup(a)===UI.achievementTab)&&(!UI.achievementQuery||(a[UI.lang].title+a[UI.lang].description).toLowerCase().includes(UI.achievementQuery.toLowerCase())));return pageTitle(T('每一点成长，都值得记住','Every little step matters'),'OUR LITTLE MILESTONES',b(T('全部领奖','Claim all')+' · '+ready.length,'claim-all-achievements','','primary','gift',!ready.length))+'<div class="card"><div class="card-head"><div class="tabs">'+Object.entries(tabs).map(([id,title])=>'<button class="tab" aria-selected="'+(id===UI.achievementTab)+'" data-act="achievement-tab" data-arg="'+id+'">'+title+'</button>').join('')+'</div><div class="row between wrap" style="margin-bottom:20px"><p class="hint">'+T('已领取 '+S.achievementClaimed.length+' / '+DATA.achievements.length+' 项','Claimed '+S.achievementClaimed.length+' / '+DATA.achievements.length)+'</p><label class="search">'+I('search')+'<input id="achievement-search" data-input="achievement-search" value="'+E(UI.achievementQuery)+'" placeholder="'+T('查找成就','Find a milestone')+'"></label></div><div class="achievement-list">'+list.map(a=>{const done=achievementComplete(a),claimed=S.achievementClaimed.includes(a.id),hidden=a.category==='hidden'&&!done;return '<article class="achievement-card"><span class="tile-icon">'+I(hidden?'lock':'award')+'</span><div class="grow"><div class="row between wrap"><h3>'+E(hidden?T('还未发现的小秘密','An undiscovered secret'):a[UI.lang].title)+'</h3>'+pill(rarityLabel(a.rarity))+'</div><p class="hint">'+E(hidden?T('继续陪伴，秘密会慢慢浮现。','Keep spending time together to discover this secret.'):a[UI.lang].description)+'</p><div class="row between" style="margin:10px 0"><small class="muted">'+Math.min(a.target,S.achievementProgress[a.id])+' / '+a.target+'</small><span class="row wrap">'+(a.coins?money(a.coins):'')+(a.hearts?money(a.hearts,'hearts'):'')+(a.item?pill(nameOf(a.item)+' ×'+a.amount):'')+(a.effect?pill(T('永久加成','Permanent bonus'),'sparkles'):'')+'</span></div>'+bar(S.achievementProgress[a.id],a.target)+'</div><div class="gap">'+b(claimed?T('已领取','Claimed'):T('领奖','Claim'),'claim-achievement',a.id,done&&!claimed?'primary small':'small','gift',!done||claimed)+(a.cg&&done?b('CG','cg','','small','image'):'')+'</div></article>';}).join('')+'</div></div>';}
function dreamRequirements(k){const d=S.dreams[k],stage=Math.min(4,d.stage),s=S.skills[k];return [{ok:S.level>=20,label:T('伙伴等级 ≥20','Companion level ≥20')},{ok:s.level>=SKILL_REQUIREMENTS[stage],label:skillName(k)+' Lv.'+SKILL_REQUIREMENTS[stage]},{ok:s.count>=SCHEDULE_REQUIREMENTS[stage],label:T('日程次数 ','Activities ')+s.count+'/'+SCHEDULE_REQUIREMENTS[stage]},{ok:s.master>=MASTER_REQUIREMENTS[stage],label:T('大师次数 ','Master completions ')+s.master+'/'+MASTER_REQUIREMENTS[stage]}];}
const allDreamsDone=()=>SKILLS.every(k=>S.dreams[k].stage===5);
const legacyCost=()=>Math.round((20000+2500*S.legacy.level**1.5)/100)*100;
function dreamsPage(){return pageTitle(T('把喜欢的事，慢慢做成梦想','Little things become big dreams'),'SOMETHING TO GROW TOWARD',b(T('奖杯柜','Trophy cabinet'),'trophies','','','award'))+'<div class="dream-grid">'+SKILLS.map(k=>{const d=S.dreams[k],copy=DATA.copy[UI.lang].dreams[k],done=d.stage>=5,req=dreamRequirements(k),cost=STAGE_COSTS[d.stage]||0,apples=APPLE_COSTS[d.stage]||0;return '<section class="dream-card card" data-tone="'+SKILL_TONES[k]+'"><div class="row between"><span class="tile-icon">'+I(SKILL_ICONS[k])+'</span>'+pill(done?T('梦想已实现','Dream fulfilled'):T('阶段 '+(d.stage+1)+' / 5','Stage '+(d.stage+1)+' / 5'))+'</div><h2 style="margin-top:18px">'+E(copy.title)+'</h2><p class="hint" style="margin-top:8px">'+E(done?copy.result:copy.summary)+'</p><div class="stage-dots">'+[1,2,3,4,5].map(i=>'<span class="'+(d.stage>=i?'done':'')+'">'+I(d.stage>=i?'check':'flower')+'<small>'+E(copy.stages[i])+'</small></span>').join('')+'</div>'+(done?'<div class="notice-box">'+I('award')+' '+T('奖杯已经收进我们的收藏。','Your trophy is in the collection.')+'</div>':'<h3>'+E(copy.stages[d.stage+1])+'</h3><div class="requirements">'+req.map(r=>'<span class="'+(r.ok?'met':'unmet')+'">'+I(r.ok?'check':'lock')+r.label+'</span>').join('')+'</div><div class="row between"><span class="hint">'+T('已投入','Invested')+'</span><strong>'+F(d.invested)+' / '+F(cost)+'</strong></div>'+bar(d.invested,cost)+investmentChoices(k,cost,d.invested,req.every(r=>r.ok))+'<p class="hint">'+T('完成阶段还需金苹果 ×'+apples+'（持有 '+S.inventory.golden_apple+'）','Complete with '+apples+' golden apples ('+S.inventory.golden_apple+' owned)')+'</p>'+b(T('完成这个阶段','Complete this stage'),'complete-dream',k,'primary block','flag',!req.every(r=>r.ok)||d.invested<cost||S.inventory.golden_apple<apples))+'</section>';}).join('')+'</div>'+legacySection();}
function trophyContent(){return fullTrophyCabinet();}
const SETTINGS_TABS=()=>({profile:[T('基本设置','General'),'settings'],appearance:[T('外观与环境','Appearance & environment'),'palette'],save:[T('存档与恢复','Saves & recovery'),'save'],share:[T('分享与名片','Sharing & cards'),'image'],updates:[T('更新','Updates'),'refresh'],help:[T('帮助与关于','Help & about'),'info']});
function settingsPage(){return pageTitle(T('把小窝调成喜欢的样子','Make yourself at home'),'YOUR LITTLE PREFERENCES')+'<div class="settings-layout"><nav class="settings-nav card" aria-label="'+T('设置分类','Setting categories')+'">'+Object.entries(SETTINGS_TABS()).map(([id,[title,icon]])=>'<button class="'+(id===UI.settings?'active':'')+'" data-act="settings-tab" data-arg="'+id+'">'+I(icon)+title+'</button>').join('')+'</nav><section class="settings-content">'+({profile:profileSettings,appearance:appearanceSettings,save:saveSettings,share:shareSettings,updates:updateSettings,help:helpSettings}[UI.settings]||profileSettings)()+'</section></div>';}
function profileSettings(){return '<section class="card"><h2>'+T('认识彼此','Getting to know each other')+'</h2><div class="profile-row">'+petImage()+'<div><h3>'+E(currentName())+'</h3><p class="hint">Lv.'+S.level+' · '+T('相伴 ','Together for ')+S.ageDays+' '+T('天','days')+'</p>'+b(T('切换角色 / Mod','Companions / Mods'),'route','roles','small','mood')+'</div></div><div class="form-grid"><label class="field"><span>'+T('伙伴的名字','Companion name')+'</span><input class="text-field" id="companion-name" data-change="name" maxlength="20" value="'+E(currentName())+'"'+(UI.edition==='bilibili'?' disabled':'')+'></label><label class="field"><span>'+T('你的生日','Your birthday')+'</span><input type="date" class="text-field" id="birthday" data-change="birthday" value="2000-'+S.birthday+'"></label><label class="field"><span>'+T('界面语言','Language')+'</span><select class="text-field" id="language" data-change="language"><option value="zh"'+(UI.lang==='zh'?' selected':'')+'>简体中文</option><option value="en"'+(UI.lang==='en'?' selected':'')+'>English</option></select></label></div>'+(UI.edition==='bilibili'?'<p class="hint" style="margin-top:15px">'+T('B 站版角色名跟随内置角色。可在预览设置切回普通版编辑。','In the Bilibili edition, built-in companion names are used. Switch to Standard in Preview controls to edit.')+'</p>':'')+'<div class="divider"></div>'+settingToggle(T('声音','Sounds'),T('照顾与奖励提示音','Care and reward sounds'),S.audio,'toggle-audio')+'<div class="row wrap" style="margin-top:20px">'+b(T('新建进度','Start fresh'),'new-confirm','','danger','plus')+b(T('版本功能说明','Edition features'),'edition-notice','','','info')+'</div>'+'</section>';}
function settingToggle(title,desc,on,action){return '<div class="row between"><div class="grow"><h3>'+title+'</h3><p class="hint">'+desc+'</p></div><button class="toggle" role="switch" aria-label="'+E(title)+'" aria-checked="'+on+'" data-act="'+action+'"><span></span></button></div>';}
function appearanceSettings(){return '<section class="card"><div class="card-head"><div><h2>'+T('小窝底色与点缀','Your backdrop & little accents')+'</h2><p class="hint">'+T('调整页面底色、品牌标记和少量强调色。每种功能仍保留自己的颜色。','Adjust the backdrop, brand and small accents. Each feature keeps its own colors.')+'</p></div>'+b(T('恢复默认','Reset colors'),'reset-theme','','small','refresh')+'</div><div class="theme-grid">'+THEMES.map(t=>'<button class="theme-choice '+(UI.theme===t.id?'active':'')+'" aria-pressed="'+(UI.theme===t.id)+'" data-act="theme" data-arg="'+t.id+'"><span class="theme-sample" style="--sample:'+t.color+';--sample-bg:'+mix('#fafbf5',t.color,.12)+'"><i></i><i></i><i></i></span><strong>'+t[UI.lang]+'</strong>'+(UI.theme===t.id?I('check'):'')+'</button>').join('')+'</div><div class="divider"></div><h3>'+T('自选点缀色','Choose an accent color')+'</h3><div class="color-row"><input id="color-picker" type="color" data-input="color-picker" value="'+UI.color+'" aria-label="'+T('主色取色器','Accent color picker')+'"><label class="field grow"><span>'+T('十六进制颜色','Hex color')+'</span><input id="color-hex" class="text-field mono" data-input="color-hex" value="'+UI.color.toUpperCase()+'" maxlength="7" aria-invalid="'+UI.customError+'" placeholder="#476B55" aria-describedby="color-error"></label>'+pill(UI.theme==='custom'?T('自定义','Custom'):T('预设配色','Preset'),'palette')+'</div><p id="color-error" class="error-text"'+(!UI.customError?' hidden':'')+'>'+T('请输入 # 加 6 位十六进制字符，保留上次有效配色。','Use # and six hexadecimal characters. The last valid color is retained.')+'</p><div class="sample-ui"><span>'+T('一点你喜欢的颜色','A little color you love')+'</span>'+pill(T('已准备好','Ready'),'check')+'<span class="button primary">'+T('强调色示例','Accent preview')+'</span></div></section><section class="card" style="margin-top:20px"><div class="card-head"><div><h2>'+T('窗外，是什么样的天气','A little weather outside')+'</h2><p class="hint">'+T('天气和季节可自由组合，立即预览，不推进时间。','Mix weather and seasons freely. Changes are immediate and do not advance time.')+'</p></div>'+b(T('恢复默认环境','Reset environment'),'reset-environment','','small','refresh')+'</div><div class="environment-controls"><div><h3>'+T('天气','Weather')+'</h3><div class="choice-grid">'+['sunny','cloudy','rainy','breezy'].map(w=>'<button class="choice-button '+(w===UI.weather?'active':'')+'" aria-pressed="'+(w===UI.weather)+'" data-act="weather" data-arg="'+w+'">'+I({sunny:'sun',cloudy:'cloud',rainy:'rain',breezy:'wind'}[w])+E(DATA.copy[UI.lang].weather[w].label)+'</button>').join('')+'</div></div><div><h3>'+T('季节','Season')+'</h3><div class="choice-grid">'+['spring','summer','autumn','winter'].map(s=>'<button class="choice-button '+(s===UI.season?'active':'')+'" aria-pressed="'+(s===UI.season)+'" data-act="season" data-arg="'+s+'">'+E(DATA.copy[UI.lang].season[s].label)+'</button>').join('')+'</div></div></div><div class="environment-preview '+environmentClass()+'">'+decor()+img('tree1')+'<div><h3>'+E(weatherLabel())+' · '+E(seasonLabel())+'</h3><p>'+environmentExplanation()+'<br>'+gardenEnvironmentExplanation()+'</p></div></div><div class="metric-grid"><div class="metric"><small>'+T('打工预估','Work estimate')+'</small><strong>+'+workReward()+'</strong><small>'+T('金币 / −'+workEnergy()+' 体力','coins / −'+workEnergy()+' energy')+'</small></div><div class="metric"><small>'+T('浇水预估','Watering saves')+'</small><strong>'+waterReduction()+'m</strong></div><div class="metric"><small>'+T('清洁额外','Extra cleaning')+'</small><strong>+'+((UI.weather==='rainy'?5:0)+(UI.season==='summer'?3:0))+'</strong></div></div><div class="row wrap" style="margin-top:20px">'+b(T('回小窝看看','See it at home'),'route','home','','flower')+b(T('去花园看看','See it in the garden'),'route','garden','','sprout')+'</div></section>';}
function saveSettings(){return saveSettingsFull();}
function sharePoster(kind='profile'){if(kind==='year')return yearReviewPoster();return '<div class="share-card"><p class="eyebrow">POCKET · A LITTLE LIFE, TOGETHER</p><h2>'+ (kind==='year'?T('一起走过的这一年','Our year together'):E(currentName())+T(' 的伙伴名片','’s companion card'))+'</h2><div class="poster-pet">'+petImage('happy')+'</div><p>'+T('第 '+S.ageDays+' 天，平凡的日子也在发光。','Day '+S.ageDays+'. There is a little glow in ordinary days.')+'</p><div class="metric-grid"><div class="metric"><small>'+T('伙伴等级','Level')+'</small><strong>'+S.level+'</strong></div><div class="metric"><small>'+T('照顾次数','Care moments')+'</small><strong>'+F(S.totalCare)+'</strong></div><div class="metric"><small>'+T('花园收获','Harvests')+'</small><strong>'+S.harvestTotal+'</strong></div></div><small>'+T('一只小伙伴，一段慢慢长大的时光。','A little companion, a life growing together.')+'</small></div>';}
function shareSettings(){return '<div class="share-grid">'+sharePoster()+'<section class="card"><h2>'+T('把这份可爱带给朋友','Share a little joy')+'</h2><p class="hint" style="margin:15px 0">'+T('生成伙伴名片，保存图片，或者复制一段问候。','Preview a companion card, save an image or copy a little greeting.')+'</p><div class="gap">'+b(T('预览名片图片','Preview card image'),'image-preview','profile','primary block','image')+b(T('保存图片','Save image'),'download-card','profile','block','download')+b(T('复制分享文字','Copy share text'),'share-copy','','block','copy')+b(T('分享应用','Share Pocket'),'share-app','','block','image')+b(T('复制示例链接','Copy demo link'),'copy-share-link','','block','copy')+b(T('查看年度回顾','Year in review'),'route','year','block','book')+'</div></section></div>';}
function updateSettings(){const u=S.update;return '<section class="card"><p class="eyebrow">POCKET · VERSION 1.7.0</p><h2>'+T('让小窝一点点变好','A little better, every day')+'</h2><p class="hint" style="margin:12px 0 24px">'+T('当前版本 1.7.0 · 所有更新过程均为本地演示。','Current version 1.7.0 · Update flows are simulated locally.')+'</p><div class="notice-box"><h3>'+({idle:T('准备检查新版本','Ready to check for updates'),checking:T('正在检查…','Checking…'),available:T('发现新版本 1.7.1','Version 1.7.1 is available'),latest:T('已经是最新版本','You’re up to date'),error:T('暂时无法连接更新服务','Unable to reach the update service'),downloaded:T('测试更新包准备完成','Demo update package is ready')})[u.state]+'</h3>'+(['available','downloaded'].includes(u.state)?'<div class="update-notes"><p>'+T('小窝界面调整，新增格子背包和花园总览，修复台词遮挡。','A refreshed home, inventory grid, garden overview and notification fixes.')+'</p><ul><li>'+T('外观配色与四季天气','Theme colors, seasons and weather')+'</li><li>'+T('更轻松的物品批量操作','Easier item selection and batch actions')+'</li></ul></div>':'')+'</div><div class="row wrap" style="margin:20px 0">'+b(T('检查更新','Check for updates'),'check-update','','primary','refresh',u.state==='checking')+b(T('版本发布页','Release page'),'release-notes','','','book')+b(T('更新前备份','Back up first'),'menu-route','save','','save')+(['available','downloaded'].includes(u.state)?b(u.state==='downloaded'?T('查看下载结果','View download result'):T('下载更新','Download update'),'download-update','','','download')+b(T('稍后提醒','Remind me later'),'later-update','','','clock')+b(T('忽略此版本','Ignore this version'),'ignore-update','','','close'):'')+'</div><p class="hint">'+(u.ignored?T('已忽略 1.7.1，再次检查可重新显示。','Version 1.7.1 is ignored. Check again to show it.'):u.later?T('演示提醒将在下次进入本页显示。','The reminder will appear on your next visit here.'):'')+'</p><div class="divider"></div>'+settingToggle(T('自动检查更新','Automatic update checks'),T('进入小窝时检查新版本','Check for a new version when entering home'),u.auto,'toggle-update')+'</section>';}
function helpSettings(){return '<section class="card"><h2>'+T('一起照顾好这段小日子','Care for a little everyday life')+'</h2><div class="gap" style="margin-top:20px">'+[['背包怎么用？','How does the bag work?','选择格子查看详情，在独立操作区调整数量。食物直接喂给伙伴，园艺物品在花园使用。','Select a tile, inspect its details and choose a quantity. Feed food from your bag; use garden supplies on a plot.'],['后期还需要打工吗？','Is work still useful later?','打工收在更多里，缺金币时商店也会提供入口。日程、花园和梦想成为后期的主要目标。','Work is under More and appears in the shop when coins are low. Activities, gardening and dreams provide longer-term goals.'],['如何查看全部天气？','How do I preview every environment?','点击天气标签，或设置 → 外观与环境。天气与季节可以独立选择，刷新恢复默认。','Click a weather label or open Settings → Appearance & environment. Weather and season are independent and reset on refresh.'],['怎么保存演示进度？','How do I keep demo progress?','存档页可以下载或复制原型专用数据。导入、恢复和云同步都只操作演示快照。','Download or copy prototype data from Saves. Import, restore and cloud sync operate only on demo snapshots.']].map(([q,qe,a,ae])=>'<details class="card soft"><summary>'+T(q,qe)+'</summary><p class="hint" style="margin-top:12px">'+T(a,ae)+'</p></details>').join('')+'</div><div class="row wrap" style="margin-top:20px">'+b(S.claimed.includes('help')?T('帮助礼包已领取','Help gift claimed'):T('领取帮助礼包','Claim help gift'),'help-gift','','primary','gift',S.claimed.includes('help'))+b(T('作者与项目','About the creator'),'author','','','heart')+b(T('介绍视频','Introduction video'),'video','','','play')+'</div></section><section class="card" style="margin-top:20px"><h2>'+T('小窝公告','Home announcements')+'</h2><p class="hint" style="margin:12px 0">'+T('新的小窝正在布置。背包和商店各司其职，通知会在屏幕顶部轻轻出现。','A refreshed home is taking shape. Your bag and shop have dedicated controls, with little messages at the top of the screen.')+'</p>'+b(T('阅读公告与礼物','Read announcement & gift'),'announcement','','','book')+'</section>';}
function rolesPage(){return pageTitle(T('想和谁一起过今天','Who will share your day?'),'OUR LITTLE COMPANIONS')+'<div class="role-grid">'+ROLES.map(r=>'<section data-tone="'+({furo:'rose',doro:'lilac',mint:'mint'})[r]+'" class="role-card card '+(S.role===r?'active':'')+'">'+petImage('happy',r)+'<h2>'+roleName(r)+'</h2><p class="hint">'+({furo:T('温柔的小陪伴','A gentle little companion'),doro:T('总有一点小惊喜','Always a little surprise'),mint:T('清新安静的小日子','Fresh, quiet little days')})[r]+'</p>'+b(S.role===r?T('正在陪伴','Your companion'):T('选择伙伴','Choose companion'),'select-role',r,S.role===r?'':'primary','heart',S.role===r)+'</section>').join('')+'</div><section class="card" style="margin-top:20px"><div class="card-head"><div><h2>'+T('我的 Mod','Your Mods')+'</h2><p class="hint">'+T('外观演示包，与内置角色共享此份示例进度。','Appearance demo packages share your current prototype progress.')+'</p></div>'+b(T('导入 Mod','Import Mod'),'mod-import','','','upload',UI.edition==='bilibili')+'</div>'+ (UI.edition==='bilibili'?'<div class="notice-box">'+T('B 站版展示内置角色，不支持导入自定义 Mod；切换普通版可体验完整流程。','Bilibili uses built-in companions. Switch to Standard to preview custom Mod imports.')+'</div>':S.mods.length?S.mods.map(m=>'<div class="mod-row"><span class="tile-icon">'+I('mood')+'</span><div class="grow"><h3>'+E(UI.lang==='en'?m.nameEn:m.name)+'</h3><p class="hint">'+(m.enabled?T('已启用 · 外观示例','Enabled · Appearance sample'):T('已导入 · 尚未启用','Imported · Not enabled'))+'</p></div>'+b(m.enabled?T('停用','Disable'):T('启用','Enable'),'toggle-mod',m.id,'small','check')+iconButton(T('删除演示 Mod','Remove demo Mod'),'delete-mod',m.id,'trash')+'</div>').join(''):'<div class="empty">'+I('mood')+T('还没有导入 Mod','No Mods imported')+'</div>')+'</section>';}
function yearPage(){return pageTitle(T('那些一起度过的小日子','All those little days together'),'OUR DAYS, TOGETHER',b(T('预览回顾图片','Preview review image'),'image-preview','year','','image'))+'<div class="share-grid year-review-layout">'+sharePoster('year')+'<section class="card year-review-details"><h2>'+T('回忆里的小足迹','Little traces of our time')+'</h2><p class="hint" style="margin:12px 0 20px">'+T('摸摸头、收一次果实、一起专心一会儿。普通的小事，也值得好好收起来。','A little head pat, a garden harvest, a quiet focus session. Everyday moments are worth keeping.')+'</p>'+reviewSummaryMarkup()+'<div class="row wrap" style="margin-top:20px">'+b(T('分享这段回忆','Share these memories'),'share-year','','primary','image')+b(T('保存回顾图片','Save review image'),'download-card','year','','download')+'</div><div class="divider"></div><h3>'+T('这段时光的纪念','Keepsakes of our time')+'</h3><div class="today-list" style="margin-top:16px">'+homeTodo('gift',T('生日的心意','A birthday gift'),T('蛋糕与小心心','Cake and hearts'),'birthday-gift')+homeTodo('flower',T('节日礼物','A seasonal celebration'),T('一份秋日问候','An autumn greeting'),'festival-gift')+homeTodo('heart',T('相伴周年','Our anniversary'),T('谢谢你一直都在','Thank you for being here'),'anniversary-gift')+homeTodo(hasMemoryArt()?'image':'lock',T('纪念插画','Commemorative illustration'),hasMemoryArt()?T('属于我们的回忆','A memory of us'):T('尚未解锁，继续收集相伴的日子','Still locked. Keep making memories together.'),'cg')+'</div></section></div>';}
function previewPage(){return pageTitle(T('预览设置','Preview controls'),'TRY A LITTLE OF EVERYTHING')+'<section class="card"><h2>'+T('选择一份示例进度','Choose a demo progress')+'</h2><p class="hint" style="margin:12px 0 20px">'+T('用于查看不同阶段的界面。仅替换演示进度，配色、天气、季节和语言保持。','Explore different stages. Only demo progress changes; colors, weather, season and language remain.')+'</p><div class="choice-grid">'+[['new',T('新手','New companion'),T('Lv.1 · 80 金币','Lv.1 · 80 coins')],['daily',T('综合日常','Everyday life'),T('Lv.24 · 全功能示例','Lv.24 · Full feature demo')],['end',T('终局','Late game'),T('Lv.99 · 梦想与传承','Lv.99 · Dreams & legacy')]].map(([id,title,desc])=>'<button class="choice-button '+(S.preset===id?'active':'')+'" data-act="preset-confirm" data-arg="'+id+'"><strong>'+title+'</strong><small>'+desc+'</small></button>').join('')+'</div><div class="divider"></div><div class="form-grid"><label class="field"><span>'+T('版本功能','Edition')+'</span><select class="text-field" id="edition" data-change="edition"><option value="standard"'+(UI.edition==='standard'?' selected':'')+'>'+T('普通版','Standard')+'</option><option value="bilibili"'+(UI.edition==='bilibili'?' selected':'')+'>'+T('B 站版','Bilibili')+'</option></select></label><label class="field"><span>'+T('语言','Language')+'</span><select class="text-field" id="preview-language" data-change="language"><option value="zh"'+(UI.lang==='zh'?' selected':'')+'>简体中文</option><option value="en"'+(UI.lang==='en'?' selected':'')+'>English</option></select></label></div><div class="row wrap" style="margin-top:20px">'+b(T('外观与环境','Colors & environment'),'appearance','','primary','palette')+b(T('重置当前示例','Reset current demo'),'preset-confirm',S.preset,'','refresh')+'</div></section><section class="card" style="margin-top:20px"><h2>'+T('往前一点点','A little forward in time')+'</h2><p class="hint" style="margin:12px 0">'+T('只推进模拟时间，方便检查成熟、结算和每日领取。','Advance simulated time to inspect growth, activity rewards and daily claims.')+'</p><div class="preview-controls">'+b('+15 '+T('分钟','minutes'),'advance','900','','clock')+b('+4 '+T('小时','hours'),'advance','14400','','clock')+b('+1 '+T('天','day'),'advance','day','','sun')+b(T('日程立即完成','Complete activity'),'advance','schedule','','calendar',!S.schedule)+b(T('专注完成本轮','Complete focus round'),'advance','focus','','coffee')+'</div></section><section class="card" style="margin-top:20px"><h2>'+T('触发一个特别时刻','Trigger a special moment')+'</h2><div class="preview-controls" style="margin-top:18px">'+[['birthday-gift','gift',T('生日','Birthday')],['festival-gift','flower',T('节日','Festival')],['anniversary-gift','heart',T('周年','Anniversary')],['trigger-return','heart',T('回归欢迎','Welcome back')],['trigger-recovery','refresh',T('存档异常','Save error')],['neighbor-gift','mood',T('邻居事件','Neighbor event')],['long-notice','message',T('长通知','Long message')],['large-numbers','coin',T('大数字','Large numbers')],['low-balance','coin',T('余额不足','Low balance')]].map(([action,icon,label])=>b(label,action,'','',''+icon)).join('')+'</div><div class="divider"></div><label class="field"><span>'+T('下次更新检查结果','Next update check result')+'</span><select class="text-field" id="update-preview" data-change="update-preview">'+[['available',T('发现新版本','Update available')],['latest',T('已是最新','Up to date')],['error',T('检查失败','Check failed')]].map(([v,label])=>'<option value="'+v+'"'+(UI.updatePreview===v?' selected':'')+'>'+label+'</option>').join('')+'</select></label></section>'+previewAdditions();}
function recoveryPage(){return recoveryPageFull();}
